export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const ha = u * u / (2 * g);
  const eps = 1e-6;
  let st = 'Ready to toss';
  if (t <= eps) st = 'Ready to toss';
  else if (t >= T - eps) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t < ta) st = 'Rising'; else st = 'Falling';
  const F = m * g;
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 250, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 270, y: 34, w: 360, h: 370, title: 'Velocity over time', state: 'v = u - g t' }));
  o.push(sdk.axis('axis.h', { x: 50, y: 370, length: 290, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const by = 370 - y / 2.2 * 290;
  const bx = 130;
  o.push(sdk.circle('ball.toss', bx, by, 24));
  o.push(...sdk.vector('vec.v', { x: bx + 20, y: by }, { value: v, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: bx - 20, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
  o.push(sdk.callout(bx + 40, 70, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'F = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  const N = 20;
  for (let i = 0; i <= N; i++) { const tt = Math.min(1.8, T) * i / N; pts.push({ x: tt, y: sdk.clamp(u - g * tt, -5.5, 5.5) }); }
  const cp = [];
  const K = 12;
  for (let i = 0; i <= K; i++) { const tt = t * i / K; cp.push({ x: tt, y: u - g * tt }); }
  const series = [{ label: 'v(t)', kind: 'line', points: pts }];
  o.push(sdk.plot('plot.vt', { x: 300, y: 70, w: 320, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series }));
  o.push(sdk.text('plot.vt.note', 460, 395, 'slope a = -g = ' + sdk.format(-g, 1), { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: ha, height: y, velocity: v, acceleration: -g, force: F, motionState: 0 } };
}
